  def genTestSuite(testCases: ISZ[(Z, ISZ[ST])]): Unit = {
    val tq = "\"\"\""

    val testRoot = Os.path(".") / "src" / "test" / "bridge"

    val ThreatEvidenceInterpreter_threatResponseProcess_threatEvidenceInterpreter_id = Arch.FrigateThreatResponseCoordinator_Instance_threatResponseProcess_threatEvidenceInterpreter.id
    val DefenseReadinessAssessor_threatResponseProcess_defenseReadinessAssessor_id = Arch.FrigateThreatResponseCoordinator_Instance_threatResponseProcess_defenseReadinessAssessor.id
    val RetreatReadinessAssessor_threatResponseProcess_retreatReadinessAssessor_id = Arch.FrigateThreatResponseCoordinator_Instance_threatResponseProcess_retreatReadinessAssessor.id
    val PrincipalResponseCoordinator_threatResponseProcess_principalResponseCoordinator_id = Arch.FrigateThreatResponseCoordinator_Instance_threatResponseProcess_principalResponseCoordinator.id
    val ThreatReportComposer_threatResponseProcess_threatReportComposer_id = Arch.FrigateThreatResponseCoordinator_Instance_threatResponseProcess_threatReportComposer.id

    def genUniqueSuiteName(path: Os.Path, prefix: String): String = {
      var i = 0
      while(true) {
        val cand = path / s"${prefix}_${i}.scala"
        if (!cand.exists) {
          return s"${prefix}_${i}"
        }
        i = i + 1
      }
      halt("Infeasible")
    }

    for (p <- testCases) {
      art.Art.BridgeId.fromZ(p._1) match {
        case ThreatEvidenceInterpreter_threatResponseProcess_threatEvidenceInterpreter_id =>
          val prefix = "ThreatEvidenceInterpreter_threatResponseProcess_threatEvidenceInterpreter_RM_TestSuite"
          val path = testRoot /+ ISZ("scp_candidate","Frigate_Threat_Response_Coordinator")
          val suiteName = genUniqueSuiteName(path, prefix)

          val testSuite =
            st"""package scp_candidate.Frigate_Threat_Response_Coordinator
                |
                |import org.sireum._
                |import scp_candidate.Frigate_Threat_Response_Coordinator._
                |
                |class ${suiteName} extends ThreatEvidenceInterpreter_threatResponseProcess_threatEvidenceInterpreter_ScalaTest {
                |  val verbose: B = T
                |
                |  ${p._2}
                |}"""
          val filename = path / s"${suiteName}.scala"
          filename.writeOver(testSuite.render)
          println(s"Wrote: ${filename.toUri}")
        case DefenseReadinessAssessor_threatResponseProcess_defenseReadinessAssessor_id =>
          val prefix = "DefenseReadinessAssessor_threatResponseProcess_defenseReadinessAssessor_RM_TestSuite"
          val path = testRoot /+ ISZ("scp_candidate","Frigate_Threat_Response_Coordinator")
          val suiteName = genUniqueSuiteName(path, prefix)

          val testSuite =
            st"""package scp_candidate.Frigate_Threat_Response_Coordinator
                |
                |import org.sireum._
                |import scp_candidate.Frigate_Threat_Response_Coordinator._
                |
                |class ${suiteName} extends DefenseReadinessAssessor_threatResponseProcess_defenseReadinessAssessor_ScalaTest {
                |  val verbose: B = T
                |
                |  ${p._2}
                |}"""
          val filename = path / s"${suiteName}.scala"
          filename.writeOver(testSuite.render)
          println(s"Wrote: ${filename.toUri}")
        case RetreatReadinessAssessor_threatResponseProcess_retreatReadinessAssessor_id =>
          val prefix = "RetreatReadinessAssessor_threatResponseProcess_retreatReadinessAssessor_RM_TestSuite"
          val path = testRoot /+ ISZ("scp_candidate","Frigate_Threat_Response_Coordinator")
          val suiteName = genUniqueSuiteName(path, prefix)

          val testSuite =
            st"""package scp_candidate.Frigate_Threat_Response_Coordinator
                |
                |import org.sireum._
                |import scp_candidate.Frigate_Threat_Response_Coordinator._
                |
                |class ${suiteName} extends RetreatReadinessAssessor_threatResponseProcess_retreatReadinessAssessor_ScalaTest {
                |  val verbose: B = T
