                |}"""
          val filename = path / s"${suiteName}.scala"
          filename.writeOver(testSuite.render)
          println(s"Wrote: ${filename.toUri}")
        case PrincipalResponseCoordinator_threatResponseProcess_principalResponseCoordinator_id =>
          val prefix = "PrincipalResponseCoordinator_threatResponseProcess_principalResponseCoordinator_RM_TestSuite"
          val path = testRoot /+ ISZ("scp_candidate","Frigate_Threat_Response_Coordinator")
