      case scp_candidate.runtimemonitor.ObservationKind.FrigateThreatResponseCoordinator_Instance_threatResponseProcess_threatEvidenceInterpreter_postInit =>
        var updates: Map[String, String] = Map.empty
        val postContainer = container.asInstanceOf[scp_candidate.Frigate_Threat_Response_Coordinator.ThreatEvidenceInterpreter_threatResponseProcess_threatEvidenceInterpreter_PostState_Container_PS]
        updates = updates + s"${bridge_id}_Out_qualifiedThreat" ~> postContainer.api_qualifiedThreat.string
